input.command:
python3 -c "
from PIL import Image
im = Image.open('barcode.png').convert('RGB')
w,h = im.size
px = im.load()
def colavg(x):
    r=g=b=0
    for y in range(h):
        p = px[x,y]
        r+=p[0]; g+=p[1]; b+=p[2]
    return (r//h, g//h, b//h)
print('--- columns 0..15 ---')
for x in range(0,16): print(x, colavg(x))
print('--- columns 925..999 ---')
for x in range(925,1000): print(x, colavg(x))
"

